if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$p=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if($p==='')$errors[]='Enter your password.';if(!$errors){$s=db()->prepare('SELECT id,full_name,email,password_hash,role FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($p,$u['password_hash']))$errors[]='Email or password is incorrect.';else{session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'full_name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role']];set_flash('success','Welcome back, '.$u['full_name'].'!');redirect('dashboard.php');}}}
render_header('Log in');?><section class="auth"><div class="intro"><p class="eyebrow">WELCOME BACK</p><h1>Your workspace,<br>all in one place.</h1><p>Sign in to manage your account, profile details, and user records.</p></div><section class="panel"><h2>Log in</h2><?php if($errors):?><div class="alert error"><?php foreach($errors as $x)echo '<p>'.e($x).'</p>';?></div><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Email address<input type="email" name="email" required value="<?=e($email)?>"></label><label>Password<div class="pw"><input id="loginpw" type="password" name="password" required><button type="button" data-show="loginpw">Show</button></div></label><button class="btn">Log in →</button></form><p class="center">New here? <a href="<?=e(BASE_URL)?>/register.php">Create an account</a></p></section></section><?php render_footer();?>
